-- PCM formulas/configuration only. Existing configuration is never overwritten.
-- Requires the existing CostOptima app_config table.
START TRANSACTION;
INSERT INTO app_config (`group`, `key`, value, type, description, is_secret, is_active, is_deleted, created_at, modified_at)
SELECT 'PCM_ENGINE', 'definition', CONVERT( USING utf8mb4), 'json', 'PCM database calculation definition', FALSE, TRUE, FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM app_config WHERE `group`='PCM_ENGINE' AND `key`='definition');
COMMIT;
